using Microsoft.EntityFrameworkCore; using AbarrotesInventory.Domain.Entities;
// espacio de nombres que organiza las clases del proyecto.
namespace AbarrotesInventory.Infrastructure.Data;
// clase principal de este archivo.
public class AppDbContext(DbContextOptions<AppDbContext> o):DbContext(o){ public DbSet<Role> Roles=>Set<Role>(); public DbSet<User> Users=>Set<User>(); public DbSet<Category> Categories=>Set<Category>(); public DbSet<Supplier> Suppliers=>Set<Supplier>(); public DbSet<Customer> Customers=>Set<Customer>(); public DbSet<Product> Products=>Set<Product>(); public DbSet<Purchase> Purchases=>Set<Purchase>(); public DbSet<PurchaseDetail> PurchaseDetails=>Set<PurchaseDetail>(); public DbSet<Sale> Sales=>Set<Sale>(); public DbSet<SaleDetail> SaleDetails=>Set<SaleDetail>(); public DbSet<InventoryMovement> InventoryMovements=>Set<InventoryMovement>(); public DbSet<Payment> Payments=>Set<Payment>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Role>().HasIndex(x=>x.Name).IsUnique();b.Entity<User>().HasIndex(x=>x.Username).IsUnique();b.Entity<Product>().HasIndex(x=>x.Code).IsUnique();b.Entity<Purchase>().HasIndex(x=>x.Number).IsUnique();b.Entity<Sale>().HasIndex(x=>x.Number).IsUnique();b.Entity<Product>().Property(x=>x.PurchasePrice).HasPrecision(18,2);b.Entity<Product>().Property(x=>x.SalePrice).HasPrecision(18,2);b.Entity<Sale>().Property(x=>x.Total).HasPrecision(18,2);b.Entity<Sale>().Property(x=>x.Subtotal).HasPrecision(18,2);b.Entity<Sale>().Property(x=>x.Tax).HasPrecision(18,2);b.Entity<Purchase>().Property(x=>x.Total).HasPrecision(18,2);b.Entity<SaleDetail>().Property(x=>x.UnitPrice).HasPrecision(18,2);b.Entity<SaleDetail>().Property(x=>x.Subtotal).HasPrecision(18,2);b.Entity<PurchaseDetail>().Property(x=>x.UnitCost).HasPrecision(18,2);b.Entity<PurchaseDetail>().Property(x=>x.Subtotal).HasPrecision(18,2);b.Entity<Payment>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<User>().HasOne(x=>x.Role).WithMany(x=>x.Users).HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Restrict);b.Entity<Product>().HasOne(x=>x.Category).WithMany(x=>x.Products).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);b.Entity<Purchase>().HasOne(x=>x.Supplier).WithMany(x=>x.Purchases).HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict);b.Entity<Purchase>().HasOne(x=>x.User).WithMany(x=>x.Purchases).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);b.Entity<Sale>().HasOne(x=>x.Customer).WithMany(x=>x.Sales).HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.Restrict);b.Entity<Sale>().HasOne(x=>x.User).WithMany(x=>x.Sales).HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict);b.Entity<Payment>().HasOne(x=>x.Sale).WithMany().HasForeignKey(x=>x.SaleId).OnDelete(DeleteBehavior.Cascade);b.Entity<PurchaseDetail>().HasOne(x=>x.Purchase).WithMany(x=>x.Details).HasForeignKey(x=>x.PurchaseId).OnDelete(DeleteBehavior.Cascade);b.Entity<SaleDetail>().HasOne(x=>x.Sale).WithMany(x=>x.Details).HasForeignKey(x=>x.SaleId).OnDelete(DeleteBehavior.Cascade);} }
